protected static boolean checkDocumentStatus(CredManDocumentStatusCheck _documentStatus)
{

    boolean isDocumentStatus = next checkDocumentStatus(_documentStatus);
    if (!isDocumentStatus)
    {
        switch (_documentStatus)
        {
            case CredManDocumentStatusCheck::METCreditCheck :
                isDocumentStatus = true;
                break;
        }
    }
    return isDocumentStatus;

}

protected internal static CredManDocumentStatusCheck documentStatus2DocumentStatusCheck(DocumentStatus _documentStatus)
{
    CredManDocumentStatusCheck credManDocumentStatusCheck ;
    credManDocumentStatusCheck =  next documentStatus2DocumentStatusCheck(_documentStatus);

    if (_documentStatus == DocumentStatus::METCreditCheck)
    {
        credManDocumentStatusCheck = CredManDocumentStatusCheck::METCreditCheck;
    }
    return credManDocumentStatusCheck;
}

protected internal static CredManDocumentStatusCheck METdocumentStatus2DocumentStatusCheck(DocumentStatus _documentStatus)
{
    CredManDocumentStatusCheck credManDocumentStatusCheck;

    switch (_documentStatus)
    {
        case DocumentStatus::Confirmation :
            credManDocumentStatusCheck = CredManDocumentStatusCheck::Confirmation;
            break;

        case DocumentStatus::PickingList :
            credManDocumentStatusCheck = CredManDocumentStatusCheck::PickingList;
            break;

        case DocumentStatus::PackingSlip :
            credManDocumentStatusCheck = CredManDocumentStatusCheck::PackingSlip;
            break;

        case DocumentStatus::Invoice :
            credManDocumentStatusCheck = CredManDocumentStatusCheck::Invoice;
            break;

        default :
            credManDocumentStatusCheck = CredManDocumentStatusCheck::NotApplicable;
            break;
    }

    return credManDocumentStatusCheck;
}

public static boolean METexist(
    CredManHoldType _holdType,
    CredManDocumentStatusCheck _documentStatus,
    NoYes _proforma)
{
    return (select firstOnly RecId from CredManStatusCheckSetup
                where CredManStatusCheckSetup.DocumentStatus == _documentStatus
                   && CredManStatusCheckSetup.HoldType == _holdType
                   && CredManStatusCheckSetup.Proforma == _proforma).RecId != 0;
}

public static boolean METhasAnyDocumentWithGraceDays(CredManHoldType _holdType, RefRecId _recId)
{
    return (select firstOnly RecId from CredManStatusCheckSetup
                where CredManStatusCheckSetup.HoldType == _holdType
                   && CredManStatusCheckSetup.RecId != _recId
                   && CredManStatusCheckSetup.GraceDays > 0).RecId != 0;
}

public static void METenableStatusCheck(
    CredManHoldType _holdType,
    CredManDocumentStatusCheck _documentStatus,
    NoYes _proforma)
{
    CredManStatusCheckSetup statusCheckSetup;

    ttsbegin;
    if (!CredManStatusCheckSetup::METexist(_holdType, _documentStatus, _proforma))
    {
        statusCheckSetup.HoldType = _holdType;
        statusCheckSetup.DocumentStatus = _documentStatus;
        statusCheckSetup.Proforma = _proforma;
        if (CredManStatusCheckSetup::METhasAnyDocumentWithGraceDays(_holdType, 0))
        {
            statusCheckSetup.GraceDays = 1;
        }

        if (statusCheckSetup.validateWrite())
        {
            statusCheckSetup.insert();
        }
    }
    ttscommit;
}

public static boolean METdisableStatusCheck(
    CredManHoldType _holdType,
    CredManDocumentStatusCheck _documentStatus,
    NoYes _proforma)
{
    boolean ret = true;
    CredManStatusCheckSetup statusCheckSetup;

    ttsbegin;
    statusCheckSetup = CredManStatusCheckSetup::METfind(_holdType, _documentStatus, _proforma, true);
    if (statusCheckSetup)
    {
        if (statusCheckSetup.validateDelete())
        {
            statusCheckSetup.delete();
        }
        else
        {
            ret = false;
        }
    }
    ttscommit;

    return ret;
}

public static void METupdateGraceDays(CredManTmpStatusCheckSetup _tmpStatusCheckSetup, CredManHoldType _holdType)
{
    ttsbegin;
    while select forupdate _tmpStatusCheckSetup
    {
        CredManStatusCheckSetup StatusCheckSetupProforma = CredManStatusCheckSetup::METfind(_holdType, _tmpStatusCheckSetup.DocumentStatus, NoYes::Yes);
        _tmpStatusCheckSetup.CheckProforma = StatusCheckSetupProforma.RecId != 0;
        _tmpStatusCheckSetup.CheckProformaGraceDays = StatusCheckSetupProforma.GraceDays;

        CredManStatusCheckSetup StatusCheckSetup = CredManStatusCheckSetup::METfind(_holdType, _tmpStatusCheckSetup.DocumentStatus, NoYes::No);
        _tmpStatusCheckSetup.CheckPosting = StatusCheckSetup.RecId != 0;
        _tmpStatusCheckSetup.CheckPostingGraceDays = StatusCheckSetup.GraceDays;

        if (_tmpStatusCheckSetup.validateWrite())
        {
            _tmpStatusCheckSetup.update();
        }
    }
    ttscommit;
}

static void METsetAllDocumentsGraceDaysToZero(CredManHoldType _holdType)
{
    CredManStatusCheckSetup credManStatusCheckSetup;

    ttsbegin;
    update_recordset credManStatusCheckSetup
        setting GraceDays = 0
        where credManStatusCheckSetup.HoldType == _holdType;
    ttscommit;
}

static void METsetDocumentsWithZeroGraceDaysToOne(CredManHoldType _holdType)
{
    CredManStatusCheckSetup credManStatusCheckSetup;

    ttsbegin;
    update_recordset credManStatusCheckSetup
        setting GraceDays = 1
        where credManStatusCheckSetup.HoldType == _holdType
           && credManStatusCheckSetup.GraceDays == 0;
    ttscommit;
}

public static boolean METhasAnyDocumentWithZeroGraceDays(CredManHoldType _holdType, RefRecId _recId)
{
    return (select firstOnly RecId from CredManStatusCheckSetup
                where CredManStatusCheckSetup.HoldType == _holdType
                   && CredManStatusCheckSetup.RecId != _recId
                   && CredManStatusCheckSetup.GraceDays == 0).RecId != 0;
}

public static CredManStatusCheckSetup METfind(
    CredManHoldType _holdType,
    CredManDocumentStatusCheck _documentStatus,
    NoYes _proforma,
    boolean _forupdate = false,
    ConcurrencyModel _concurrencyModel = ConcurrencyModel::Auto)
{
    CredManStatusCheckSetup statusCheckSetup = null;

    statusCheckSetup.selectForUpdate(_forupdate);

    if (_forUpdate && _concurrencyModel != ConcurrencyModel::Auto)
    {
        statusCheckSetup.concurrencyModel(_concurrencyModel);
    }

    select firstOnly statusCheckSetup
        where statusCheckSetup.DocumentStatus == _documentStatus &&
              statusCheckSetup.HoldType == _holdType &&
              statusCheckSetup.Proforma == _proforma;

    return statusCheckSetup;
}
